
.form-root {
  max-width: 640px;
}

.fh {
  padding: 9px 12px;
  background: linear-gradient(180deg, #221c14, var(--sb-panel));
  border-bottom: 1px solid var(--sb-line);
}

.ft {
  font-size: 15px;
  font-weight: bold;
  color: var(--sb-song);
  letter-spacing: 1px;
}

.fs {
  font-size: 11px;
  margin-top: 3px;
}

.sb-pad > * + * {
  margin-top: 8px;
}

.openings {
  display: grid;
  gap: 5px;
}

.op {
  display: flex;
  gap: 7px;
  align-items: flex-start;
  border: 1px solid var(--sb-line);
  background: var(--sb-bg);
  padding: 6px 8px;
  cursor: pointer;
  transition: all 0.18s;
}

.op:hover {
  border-color: var(--sb-song);
}

.op.on {
  border-color: var(--sb-song);
  background: #221c14;
}

.op input {
  margin-top: 3px;
  accent-color: var(--sb-song);
  flex: none;
}

.ol {
  flex: 1;
  min-width: 0;
}

.ol b {
  font-size: 13px;
  margin-right: 5px;
}

.od {
  font-size: 11px;
  margin-top: 2px;
}

.frow {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}

.frow > label {
  flex: none;
  width: 84px;
  color: var(--sb-dim);
  font-size: 12px;
}

.frow input[type='text'],
.frow input[type='number'],
.frow select,
textarea {
  flex: 1;
  min-width: 160px;
  background: var(--sb-bg);
  border: 1px solid var(--sb-line);
  color: var(--sb-text);
  font-family: var(--sb-font);
  font-size: 12px;
  padding: 3px 6px;
  outline: none;
}

.frow input:focus,
.frow select:focus,
textarea:focus {
  border-color: var(--sb-song);
}

.frow.check {
  align-items: flex-start;
}

.frow.check label {
  width: auto;
  flex: 1;
  color: var(--sb-text);
  display: flex;
  gap: 6px;
  align-items: center;
  cursor: pointer;
}

.frow.check input {
  accent-color: var(--sb-song);
}

textarea {
  width: 100%;
  resize: vertical;
  line-height: 1.5;
}

.submit-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding-top: 2px;
}

.submit-row .sb-btn {
  font-size: 13px;
  padding: 6px 18px;
}

.submit-row .sb-dim {
  font-size: 11px;
  flex: 1;
  min-width: 140px;
}
